function CashflowSaeulen({ jahre, foerderEnde }) {
  const W = 480;
  const H = 120;
  const max = Math.max(...jahre.map((j) => Math.abs(j.cf)));
  const b = W / jahre.length;
  const null0 = H * 0.86; // Nulllinie – Platz für negative Jahre
  const iEnde = jahre.findIndex((j) => j.jahr > foerderEnde);
  return (
    <svg viewBox={`0 0 ${W} ${H + 20}`} className="block h-auto w-full" aria-hidden="true">
      {iEnde > 0 && <rect x={iEnde * b} y="0" width={W - iEnde * b} height={H} fill="#1f5aa1" fillOpacity="0.08" />}
      {jahre.map((j, i) => {
        const h = (Math.abs(j.cf) / max) * null0 * 0.95;
        const neg = j.cf < 0;
        return (
          <rect
            key={j.jahr}
            x={i * b + 1.5}
            y={neg ? null0 : null0 - h}
            width={b - 3}
            height={Math.max(neg ? Math.min(h, H - null0) : h, 1.5)}
            rx="1.5"
            fill={neg ? "#e5a900" : j.gefoerdert ? "#669933" : "#1f5aa1"}
          />
        );
      })}
      <line x1="0" x2={W} y1={null0} y2={null0} stroke="#03122b" strokeOpacity="0.25" />
      {iEnde > 0 && <line x1={iEnde * b} x2={iEnde * b} y1="0" y2={H} stroke="#1f5aa1" strokeDasharray="3 3" />}
      <text x="0" y={H + 16} fontSize="11" fill="#5b6475">{jahre[0].jahr}</text>
      {iEnde > 0 && <text x={iEnde * b + 4} y="12" fontSize="11" fill="#1f5aa1" fontWeight="600">Förderende {foerderEnde}</text>}
      <text x={W} y={H + 16} fontSize="11" fill="#5b6475" textAnchor="end">{jahre.at(-1).jahr}</text>
    </svg>
  );
}

