      <div className="ov-hero-in relative mx-3 -mt-3 rounded-2xl bg-navy-900/95 p-4 text-white shadow-e4 ring-1 ring-white/12 backdrop-blur sm:absolute sm:-bottom-16 sm:-left-8 sm:mx-0 sm:mt-0 sm:w-[270px] lg:-left-12" style={{ "--ov-delay": "620ms" }}>
